import XCTest
@testable import MirNavigation
final class EquipmentReplayTests:XCTestCase {
    func testLiveEquipmentFrames() throws {
        let frames=[
            "4167685f6460686a646f4d4b6764686b666468676464686b6565686b6464686b6b64485f6460686a5c64686b6464686b5f6468636478686b6464506b646268686469686b673c",
            "",
            "53534f4c536c6a5d6464686b6464686b",
            "6466686b646f6a6a6464686b6464686b",
            "4167685f6460686a646f4d4b6764686b666468676464686b6766686a6464686b5d64486b6460686a5c64686b6464686b5f6468636478686b6464596b646268686469676b673c",
            "4167685f6460686a646f4d4b6764686b666468676464686b6766686a6464686b5d64486b6460686a5c64686b6464686b5f6468636478686b6464596b646268686469676b673c",
            "",
            "",
            "",
            "6466686b646f6a6a6464686b6464686b",
            "4167685f6460686a646f4d4b6764686b666468676464686b6766686a6464686b5f64486b6460686a5c64686b6464686b5f6468636478686b6464596b646268686469676b673c",
            "",
            "6464686b646f6a696464686b6464686b",
            "4167685f6460686a646f4d4b6764686b666468676464686b6565686b6464686b5f64486b6460686a5c64686b6464686b5f6468636478686b6464506b646268686469686b673c",
            "52534f4c536c6a5c6464686b6464686b",
            "4167685f6460686a646f4d4b6764686b666468676464686b6565686b6464686b5c6448676460686a5c64686b6464686b5f6468636478686b6464506b646268686469686b673c",
            "",
        ]
        var ids=Set<UInt16>()
        for hex in frames {
            let a=Array(hex),raw=stride(from:0,to:a.count,by:2).map{UInt8(String(a[$0...($0+1)]),radix:16)!}
            let p=try MirWire.packet(raw);ids.insert(p.id)
            if [UInt16(200),202,203].contains(p.id) { XCTAssertNotNil(MirEquipment.item(p.body)) }
            if p.id==201 { for item in p.bodyParts { XCTAssertNotNil(MirEquipment.item(item)) } }
            if p.id==621 { for i in stride(from:1,to:p.bodyParts.count,by:2) { XCTAssertNotNil(MirEquipment.item(p.bodyParts[i])) } }
        }
        XCTAssertTrue(Set<UInt16>([52,201,615,616,619,620,621]).isSubset(of:ids))
    }
}
